-- Generated by pc2dbt from mapping m_FL_JS_MARTS_CORE (L3107–4053), target ORDER_ITEMS (L1172–1184).
-- Lines refer to the PowerCenter XML. FLAG comments mark behaviour copied as-is (decision D1); see flags.md.

with
-- SQ_STG_ORDER_ITEMS · Source Qualifier · L3148–3163 · reads STG_ORDER_ITEMS (L1039–1043), which another mapping writes: ref() (decision Q5)
sq_stg_order_items as (
    select
        stg_order_items.order_item_id,
        stg_order_items.order_id,
        stg_order_items.product_id
    from {{ ref('stg_order_items') }} as stg_order_items
),

-- SQ_STG_ORDERS · Source Qualifier · L3164–3186 · reads STG_ORDERS (L1044–1055), which another mapping writes: ref() (decision Q5)
sq_stg_orders as (
    select
        stg_orders.order_id,
        stg_orders.ordered_at_day
    from {{ ref('stg_orders') }} as stg_orders
),

-- JNR_ORDER_ITEMS_ORDERS · Joiner · L3187–3205 · Normal Join
jnr_order_items_orders as (
    select
        detail.order_item_id,
        detail.order_id,
        detail.product_id,
        master.ordered_at_day
    from sq_stg_order_items as detail
    inner join sq_stg_orders as master
        on master.order_id = detail.order_id
),

-- SQ_STG_PRODUCTS1 · Source Qualifier · L3206–3226 · reads STG_PRODUCTS (L1029–1038), which another mapping writes: ref() (decision Q5)
sq_stg_products1 as (
    select
        stg_products.product_id,
        stg_products.product_name,
        stg_products.product_type,
        stg_products.product_price,
        stg_products.is_food_item,
        stg_products.is_drink_item
    from {{ ref('stg_products') }} as stg_products
),

-- JNR_ADD_PRODUCTS · Joiner · L3227–3250 · Normal Join
jnr_add_products as (
    select
        detail.order_item_id,
        detail.order_id,
        detail.product_id,
        detail.ordered_at_day,
        master.product_name,
        master.product_type,
        master.product_price,
        master.is_food_item,
        master.is_drink_item
    from jnr_order_items_orders as detail
    inner join sq_stg_products1 as master
        on master.product_id = detail.product_id
),

-- SQ_STG_SUPPLIES1 · Source Qualifier · L3251–3269 · reads STG_SUPPLIES (L1021–1028), which another mapping writes: ref() (decision Q5)
sq_stg_supplies1 as (
    select
        stg_supplies.supply_id,
        stg_supplies.supply_name,
        stg_supplies.supply_cost_cents,
        stg_supplies.supply_cost,
        stg_supplies.is_perishable,
        stg_supplies.product_id
    from {{ ref('stg_supplies') }} as stg_supplies
),

-- SRT_SUPPLIES · Sorter · L3270–3286 · dropped: row order means nothing in a table (decision Q12)
-- AGG_SUPPLIES_BY_PRODUCT · Aggregator · L3287–3302
agg_supplies_by_product as (
    select
        sq_stg_supplies1.product_id,
        sum(sq_stg_supplies1.supply_cost) as supply_cost_per_product,
        max(sq_stg_supplies1.is_perishable) as has_perishable_supply
    from sq_stg_supplies1
    group by sq_stg_supplies1.product_id
),

-- JNR_ADD_SUPPLY_COST · Joiner · L3303–3328 · Master Outer Join
jnr_add_supply_cost as (
    select
        master.order_item_id,
        master.order_id,
        detail.product_id,
        master.ordered_at_day,
        master.product_name,
        master.product_type,
        master.product_price,
        master.is_food_item,
        master.is_drink_item,
        detail.supply_cost_per_product,
        detail.has_perishable_supply
    from agg_supplies_by_product as detail
    left join jnr_add_products as master  -- FLAG master_outer L3319: JNR_ADD_SUPPLY_COST is a Master Outer Join: it keeps every row from AGG_SUPPLIES_BY_PRODUCT (detail) and only the rows from JNR_ADD_PRODUCTS (master) that match; JNR_ADD_PRODUCTS rows with no match are dropped
        on master.product_id = detail.product_id
),

-- EXP_ORDER_ITEMS_CALC · Expression · L3329–3344
exp_order_items_calc as (
    select
        jnr_add_supply_cost.order_item_id,
        jnr_add_supply_cost.order_id,
        jnr_add_supply_cost.product_id,
        jnr_add_supply_cost.ordered_at_day,
        jnr_add_supply_cost.product_name,
        jnr_add_supply_cost.product_type,
        jnr_add_supply_cost.product_price,
        jnr_add_supply_cost.is_food_item,
        jnr_add_supply_cost.is_drink_item,
        case when (jnr_add_supply_cost.supply_cost_per_product is null) then 0 else jnr_add_supply_cost.supply_cost_per_product end as supply_cost_per_product,
        case when (jnr_add_supply_cost.has_perishable_supply is null) then 0 else jnr_add_supply_cost.has_perishable_supply end as has_perishable_supply
    from jnr_add_supply_cost
)

select
    cast(exp_order_items_calc.order_item_id as varchar) as order_item_id,
    cast(exp_order_items_calc.order_id as varchar) as order_id,
    cast(exp_order_items_calc.product_id as varchar) as product_id,
    cast(exp_order_items_calc.ordered_at_day as timestamp) as ordered_at_day,
    cast(exp_order_items_calc.product_name as varchar) as product_name,
    cast(exp_order_items_calc.product_type as varchar) as product_type,
    cast(exp_order_items_calc.product_price as decimal(12,2)) as product_price,
    cast(exp_order_items_calc.is_food_item as decimal(1,0)) as is_food_item,
    cast(exp_order_items_calc.is_drink_item as decimal(1,0)) as is_drink_item,
    cast(exp_order_items_calc.supply_cost_per_product as decimal(12,2)) as supply_cost_per_product,
    cast(exp_order_items_calc.has_perishable_supply as decimal(1,0)) as has_perishable_supply
from exp_order_items_calc
